-- Deterministic seed data for the local fashion catalog (Task 4A).
-- Generated once (not at runtime) via a deterministic script: fixed brand/
-- product/color/size lists cycled by index, UUIDs derived with uuid5 from a
-- fixed namespace, so re-running this migration is idempotent and reproducible.

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (product_id, occasion_tag) DO NOTHING;

ON CONFLICT (product_id, style_tag) DO NOTHING;

ON CONFLICT (product_id, weather_tag) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;
